function getAcademicGroupD() {
  const allLabs = [];
  const labIds = [
    'subj-lab-circuits',
    'subj-lab-logic',
    'subj-lab-electronics',
    'subj-lab-datastruct',
    'subj-lab-assembly',
    'subj-lab-arch',
    'subj-lab-physics',
    'subj-lab-chemistry',
    'subj-lab-control'
  ];

  for (const labId of labIds) {
    // 1. Get existing authentic questions from db
    const existingMid = db.questions.filter(q => q.quizId === `quiz-${labId}-mid`);
    const existingFin = db.questions.filter(q => q.quizId === `quiz-${labId}-final`);

    // 2. Add existing to list
    allLabs.push(...existingMid);
    allLabs.push(...existingFin);

    // 3. Append supplements to reach exactly 32 Mid and 52 Final
    const supp = labSupplements[labId];
    if (supp) {
      // Mid supplement
      const midNeeded = 32 - existingMid.length;
      for (let i = 0; i < midNeeded; i++) {
        if (i < supp.mid.length) {
          const item = supp.mid[i];
          const newId = `${labId.replace('subj-','').toUpperCase()}-MID-SUPP-${String(i+1).padStart(2, '0')}`;
          allLabs.push(createQuestion(newId, labId, false, item[0], item[1], item[2], item[3], item[4], item[5], 'Medium', 'University Lab Manual Exam.pdf', existingMid.length + i));
        }
      }

      // Final supplement
      const finNeeded = 52 - existingFin.length;
      for (let i = 0; i < finNeeded; i++) {
        if (i < supp.final.length) {
          const item = supp.final[i];
          const newId = `${labId.replace('subj-','').toUpperCase()}-FIN-SUPP-${String(i+1).padStart(2, '0')}`;
          allLabs.push(createQuestion(newId, labId, true, item[0], item[1], item[2], item[3], item[4], item[5], 'Medium', 'University Lab Final Exam.pdf', existingFin.length + i));
        }
      }
    }
  }

  return allLabs;
}

module.exports = { getAcademicGroupD };
